def solve(grid):
    rows = len(grid)
    cols = len(grid[0])

    interior = set()
    for r in range(rows):
        five_cols = [c for c in range(cols) if grid[r][c] == 5]
        if len(five_cols) >= 2:
            left = min(five_cols)
            right = max(five_cols)
            for c in range(left + 1, right):
                if grid[r][c] != 5:
                    interior.add((r, c))

    if not interior:
        return grid

    interior_twos = [(r, c) for r, c in interior if grid[r][c] == 2]

    min_r = min(r for r, c in interior)
    max_r = max(r for r, c in interior)
    min_c = min(c for r, c in interior)
    max_c = max(c for r, c in interior)

    out_h = max_r - min_r + 1
    out_w = max_c - min_c + 1

    col_counts = [0] * out_w
    for r, c in interior_twos:
        col_counts[c - min_c] += 1

    output = [[0] * out_w for _ in range(out_h)]
    for oc in range(out_w):
        for i in range(col_counts[oc]):
            output[out_h - 1 - i][oc] = 2

    return output
